insert into public.company_brands
  (id, company_id, slug, name, sort_order, is_active, created_at, updated_at)
select definition.id, 'kids-velvet', definition.slug, definition.name,
       definition.sort_order, true, now(), now()
from kv_complete_catalog_seed seed
cross join lateral jsonb_to_recordset(seed.payload -> 'brands')
  as definition(id text, slug text, name text, "sortOrder" integer)
on conflict (company_id, slug) do update
set name = excluded.name,
    sort_order = excluded.sort_order,
    is_active = true,
    updated_at = now();

insert into public.company_categories
  (id, company_id, slug, name, parent_id, brand_id, sort_order, is_active, created_at, updated_at)
select definition.id, 'kids-velvet', definition.slug,
       jsonb_build_object('en', definition."nameEn", 'ar', definition."nameAr"),
       null, brand.id, definition."sortOrder", true, now(), now()
from kv_complete_catalog_seed seed
cross join lateral jsonb_to_recordset(seed.payload -> 'mains')
  as definition(
    id text, "brandSlug" text, "canonicalSlug" text, slug text,
    "nameEn" text, "nameAr" text, "sortOrder" integer
  )
join public.company_brands brand
  on brand.company_id = 'kids-velvet'
 and brand.slug = definition."brandSlug"
on conflict (company_id, slug) do update
set name = excluded.name,
    parent_id = null,
    brand_id = excluded.brand_id,
    sort_order = excluded.sort_order,
    is_active = true,
    updated_at = now();

insert into public.company_categories
  (id, company_id, slug, name, parent_id, brand_id, sort_order, is_active, created_at, updated_at)
select definition.id, 'kids-velvet', definition.slug,
       jsonb_build_object('en', definition."nameEn", 'ar', definition."nameAr"),
       main.id, main.brand_id, definition."sortOrder", true, now(), now()
from kv_complete_catalog_seed seed
cross join lateral jsonb_to_recordset(seed.payload -> 'subs')
  as definition(
    id text, "brandSlug" text, "mainId" text, "canonicalSlug" text, slug text,
    "nameEn" text, "nameAr" text, "sortOrder" integer
  )
join public.company_categories main
  on main.company_id = 'kids-velvet'
 and main.id = definition."mainId"
 and main.parent_id is null
join public.company_brands brand
  on brand.company_id = main.company_id
 and brand.id = main.brand_id
 and brand.slug = definition."brandSlug"
on conflict (company_id, slug) do update
set name = excluded.name,
    parent_id = excluded.parent_id,
    brand_id = excluded.brand_id,
    sort_order = excluded.sort_order,
    is_active = true,
    updated_at = now();

do $$
declare
  brand_count integer;
  main_count integer;
  sub_count integer;
  legacy_count integer;
  resolved_products integer;
begin
  select count(*) into brand_count
  from public.company_brands
  where company_id = 'kids-velvet'
    and slug in (select value ->> 'slug' from kv_complete_catalog_seed, jsonb_array_elements(payload -> 'brands'));

  select count(*) into main_count
  from public.company_categories
  where company_id = 'kids-velvet'
    and parent_id is null
    and brand_id is not null;

  select count(*) into sub_count
  from public.company_categories
  where company_id = 'kids-velvet'
    and parent_id is not null;

  select count(*) into legacy_count
  from public.company_categories
  where company_id = 'kids-velvet'
    and parent_id is null
    and brand_id is null;

  select count(*) into resolved_products
  from public.products product
  join public.company_brands brand
    on brand.company_id = product.company_id and brand.id = product.brand_id
  join public.company_categories main
    on main.company_id = product.company_id
   and main.id = product.data ->> 'mainCategoryId'
   and main.parent_id is null
   and main.brand_id = brand.id
  join public.company_categories sub
    on sub.company_id = product.company_id
   and sub.id = product.data ->> 'subcategoryId'
   and sub.parent_id = main.id
   and sub.brand_id = brand.id
  where product.company_id = 'kids-velvet'
    and product.slug in (
      'pocket-worlds-starter-set', 'odd-pals-plush',
      'tiny-table-bake-studio', 'neon-racers-twin-pack',
      'bloom-pets-surprise-pod', 'splash-lab-water-blaster',
      'build-club-maker-kit', 'cloud-dough-color-pack'
    );

  if brand_count <> 12 then
    raise exception 'Migration 021 expected 12 canonical Kids Velvet brands, found %.', brand_count;
  end if;
  if main_count <> 127 then
    raise exception 'Migration 021 expected 127 brand-linked Main Categories, found %.', main_count;
  end if;
  if sub_count <> 412 then
    raise exception 'Migration 021 expected 412 Subcategories, found %.', sub_count;
  end if;
  if legacy_count < 7 then
    raise exception 'Migration 021 expected the 7 legacy global categories to remain, found %.', legacy_count;
  end if;
  if resolved_products <> 8 then
    raise exception 'Migration 021 expected 8 existing resolved products, found %.', resolved_products;
  end if;
end $$;

commit;

